import{_ as n,o,c as i,a3 as r}from"./chunks/framework.DX_KL3e0.js";const m=JSON.parse('{"title":"Gửi ticket hỗ trợ","description":"","frontmatter":{},"headers":[],"relativePath":"huong-dan/gui-ticket.md","filePath":"huong-dan/gui-ticket.md","lastUpdated":1782145431000}'),a={name:"huong-dan/gui-ticket.md"};function e(h,t,g,s,c,l){return o(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="gui-ticket-ho-tro" tabindex="-1">Gửi ticket hỗ trợ <a class="header-anchor" href="#gui-ticket-ho-tro" aria-label="Permalink to &quot;Gửi ticket hỗ trợ&quot;">​</a></h1><blockquote><p><strong>🎯 Mục tiêu:</strong> Gửi một yêu cầu hỗ trợ tới đúng bộ phận và theo dõi đến khi xong. <strong>👤 Ai làm được:</strong> Mọi người dùng. · <strong>⏱️ Khoảng:</strong> 2–3 phút.</p></blockquote><h2 id="cac-buoc" tabindex="-1">Các bước <a class="header-anchor" href="#cac-buoc" aria-label="Permalink to &quot;Các bước&quot;">​</a></h2><ol><li>Vào <strong>Ticket Hỗ Trợ</strong> (menu nhóm <em>Hoạt Động</em>) → nhấn <strong>Tạo ticket</strong> ở góc phải.</li><li>Điền cửa sổ <strong>Tạo Ticket Mới</strong>: <ul><li><strong>Tiêu Đề</strong> * — mô tả ngắn gọn vấn đề.</li><li><strong>Loại Yêu Cầu</strong> + <strong>Danh Mục / Danh Mục Chi Tiết</strong> * — phân loại ticket.</li><li><strong>Mô Tả Chi Tiết</strong>, <strong>Độ Ưu Tiên</strong> (Thấp / Trung bình / Cao).</li><li><strong>Đơn Vị Xử Lý</strong> + <strong>Người Được Giao</strong> — tìm theo tên, chức vụ, phòng ban.</li><li><strong>Tệp đính kèm</strong> nếu cần (mỗi tệp ≤ 10MB).</li></ul></li><li>Nhấn nút tạo để gửi.</li></ol><h2 id="✅-ket-qua" tabindex="-1">✅ Kết quả <a class="header-anchor" href="#✅-ket-qua" aria-label="Permalink to &quot;✅ Kết quả&quot;">​</a></h2><p>Ticket xuất hiện ở tab <strong>Đã gửi</strong>. Trạng thái chạy theo: <strong>Đã gửi → Đang xử lý → Đã hoàn thành → Đóng</strong>.</p><h2 id="💡-meo-luu-y" tabindex="-1">💡 Mẹo &amp; lưu ý <a class="header-anchor" href="#💡-meo-luu-y" aria-label="Permalink to &quot;💡 Mẹo &amp; lưu ý&quot;">​</a></h2><ul><li>Chọn đúng <strong>Danh Mục</strong> + <strong>Đơn Vị Xử Lý</strong> để ticket tới đúng người, xử lý nhanh hơn.</li><li>Trao đổi thêm: mở ticket → tab <strong>Bình luận</strong> (nhắc tên đồng nghiệp để họ nhận thông báo).</li><li>Ticket <strong>Đã hoàn thành</strong> sẽ <strong>tự đóng sau 3 ngày</strong> — nếu vấn đề chưa xong, thêm bình luận trước đó.</li></ul><p><em>Chi tiết: <a href="/help/chuc-nang/tickets.html">Ticket Hỗ Trợ</a></em></p>',9)])])}const k=n(a,[["render",e]]);export{m as __pageData,k as default};
